          "code": "import torch, torch.nn.functional as F\nfrom torchvision.models import vgg19, VGG19_Weights\n\nvgg = vgg19(weights=VGG19_Weights.DEFAULT).features.eval().requires_grad_(False)  # FROZEN\nSTYLE_L, CONTENT_L = [0, 5, 10, 19, 28], [21]        # conv1_1..conv5_1 ; conv4_2\n\ndef features(x, layers):\n    out, h = {}, x\n    for i, layer in enumerate(vgg):\n        h = layer(h)\n        if i in layers: out[i] = h\n    return out\n\ndef gram(f):                                          # (1,C,H,W) -> (C,C), normalized\n    _, c, h, w = f.shape\n    f = f.reshape(c, h * w)\n    return (f @ f.T) / (c * h * w)\n\ncontent_t = features(content_img, CONTENT_L)\nstyle_t   = {i: gram(f) for i, f in features(style_img, STYLE_L).items()}\n\nx = content_img.clone().requires_grad_(True)          # THE OPTIMIZATION VARIABLE is the image\nopt = torch.optim.LBFGS([x], max_iter=500)\nALPHA, BETA = 1.0, 1e6                                # style weight >> content weight\n\ndef closure():\n    opt.zero_grad()\n    f = features(x, STYLE_L + CONTENT_L)\n    l_content = sum(F.mse_loss(f[i], content_t[i]) for i in CONTENT_L)\n    l_style   = sum(F.mse_loss(gram(f[i]), style_t[i]) for i in STYLE_L)\n    loss = ALPHA * l_content + BETA * l_style\n    loss.backward()\n    return loss\n\nopt.step(closure)                                     # ~1-3 min for one 512px image on a GPU",
